
from agent_security.events import AgentEvent
from agent_security.database import EventDatabase


class EventMonitor:
    """Collects and tracks events generated by AI agents."""

    def __init__(self, database=None):
        self.database = database or EventDatabase()

    def collect_event(self, event: AgentEvent):
        """Collect and persist one agent event."""
        self.database.save_event(event)

    def collect_events(self, events: list[AgentEvent]):
        """Collect and persist multiple agent events."""
        if not events:
            return

        self.database.save_events(events)

    def get_events(self):
        """Return all collected events."""
        return self.database.get_events()

    def get_summary(self):
        """Return basic statistics about collected events."""
        events = self.get_events()

        total = len(events)
        successful = sum(event.status == "success" for event in events)
        failed = sum(event.status == "failure" for event in events)
        blocked = sum(event.status == "blocked" for event in events)

        return {
            "total_events": total,
            "successful_events": successful,
            "failed_events": failed,
            "blocked_events": blocked
        }

    def clear_events(self):
        """Clear all stored events."""
        self.database.clear_events()
